int decode_chunk(const char* chunk, int len, char* out, int out_cap) {
    if (!chunk || !out || len <= 0) {
        return -1;
    }

    int i = 0;

    // 1. Parse the chunk size (hexadecimal string)
    unsigned long chunk_size = 0;
    bool has_size = false;

    while (i < len) {
        char c = chunk[i];
        // Ignore leading whitespace if any (though standard HTTP doesn't strictly require it before size)
        if (c == '\r' && i + 1 < len && chunk[i + 1] == '\n') {
            i += 2;
            break;
        }
        if (c == '\n') {
            i += 1;
            break;
        }

        // Stop parsing size at chunk extensions (semicolon) or CRLF
        if (c == ';') {
            // Skip until CRLF
            while (i < len) {
                if (chunk[i] == '\r' && i + 1 < len && chunk[i + 1] == '\n') {
                    i += 2;
                    break;
                }
                if (chunk[i] == '\n') {
                    i += 1;
                    break;
                }
                i++;
            }
            break;
        }

        int digit = -1;
        if (c >= '0' && c <= '9') digit = c - '0';
        else if (c >= 'a' && c <= 'f') digit = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') digit = c - 'A' + 10;

        if (digit >= 0) {
            has_size = true;
            // Prevent overflow
            if (chunk_size > (unsigned long)(((unsigned long)(-1)) >> 4)) {
                return -1; // Overflow
            }
            chunk_size = (chunk_size << 4) + digit;
        } else {
            // Invalid hex character before size termination
            return -1;
        }
        i++;
    }

    if (!has_size) {
        return -1;
    }

    // If chunk_size is 0, this is the last chunk
    if (chunk_size == 0) {
        return 0;
    }

    // Check if we have enough data for the chunk data plus trailing CRLF
    if (i + (long)chunk_size > len) {
        return -1; // Incomplete chunk data
    }

    // Check if output capacity is sufficient
    if ((unsigned long)out_cap < chunk_size) {
        return -1; // Output buffer too small
    }

    // Copy chunk data to output
    std::memcpy(out, &chunk[i], chunk_size);

    return (int)chunk_size;
}

