int rotate_log(const char* path) {
    if (!path) {
        return -1;
    }

    // Create a temporary file in the same directory as path to ensure atomic rename later
    size_t path_len = std::strlen(path);
    char* tmp_path = (char*)std::malloc(path_len + 8);
    if (!tmp_path) {
        return -1;
    }

    std::snprintf(tmp_path, path_len + 8, "%s.XXXXXX", path);

    int fd = mkstemp(tmp_path);
    if (fd == -1) {
        std::free(tmp_path);
        return -1;
    }

    // Ensure proper permissions on the temp log file
    if (fchmod(fd, S_IRUSR | S_IWUSR) == -1) {
        close(fd);
        unlink(tmp_path);
        std::free(tmp_path);
        return -1;
    }

    // Open the existing log file for reading if it exists
    int src_fd = open(path, O_RDONLY);
    if (src_fd != -1) {
        char buffer[8192];
        ssize_t bytes_read;

        while ((bytes_read = read(src_fd, buffer, sizeof(buffer))) > 0) {
            ssize_t bytes_written = 0;
            while (bytes_written < bytes_read) {
                ssize_t w = write(fd, buffer + bytes_written, bytes_read - bytes_written);
                if (w <= 0) {
                    break;
                }
                bytes_written += w;
            }
            if (bytes_written != bytes_read) {
                break;
            }
        }
        close(src_fd);
    }

    // Close the temporary file descriptor to finalize writes before renaming
    if (close(fd) == -1) {
        unlink(tmp_path);
        std::free(tmp_path);
        return -1;
    }

    // Atomically replace the old log with the new rotated log
    if (rename(tmp_path, path) == -1) {
        unlink(tmp_path);
        std::free(tmp_path);
        return -1;
    }

    std::free(tmp_path);
    return 0;
}

