int rotate_log(const char* path) {
    if (!path) {
        return -1;
    }

    // Create a temporary file in the same directory as path to ensure atomic rename
    // Construct the template for mkstemp: dirname + "/log_temp_XXXXXX"
    size_t path_len = strlen(path);
    char* tmpl = (char*)malloc(path_len + 16);
    if (!tmpl) {
        return -1;
    }

    strcpy(tmpl, path);
    char* last_slash = strrchr(tmpl, '/');
    if (last_slash) {
        *(last_slash + 1) = '\0';
        strcat(tmpl, "log_temp_XXXXXX");
    } else {
        strcpy(tmpl, "log_temp_XXXXXX");
    }

    int temp_fd = mkstemp(tmpl);
    if (temp_fd == -1) {
        free(tmpl);
        return -1;
    }

    // Ensure the temporary file has appropriate permissions (e.g., 0644)
    struct stat st;
    if (stat(path, &st) == 0) {
        fchmod(temp_fd, st.st_mode & 0777);
    } else {
        fchmod(temp_fd, 0644);
    }

    // Open the original log file for reading
    int orig_fd = open(path, O_RDONLY);
    if (orig_fd == -1) {
        // If the original log doesn't exist yet, we can just rename the temp to path
        close(temp_fd);
        if (rename(tmpl, path) != 0) {
            unlink(tmpl);
            free(tmpl);
            return -1;
        }
        free(tmpl);
        return 0;
    }

    // Copy contents from original log to temporary file
    char buffer[8192];
    ssize_t bytes_read, bytes_written;
    int success = 1;

    while ((bytes_read = read(orig_fd, buffer, sizeof(buffer))) > 0) {
        char* ptr = buffer;
        while (bytes_read > 0) {
            bytes_written = write(temp_fd, ptr, bytes_read);
            if (bytes_written <= 0) {
                success = 0;
                break;
            }
            bytes_read -= bytes_written;
            ptr += bytes_written;
        }
        if (!success) {
            break;
        }
    }

    if (bytes_read < 0) {
        success = 0;
    }

    // Close file descriptors
    close(orig_fd);

    // Ensure data is flushed to disk
    if (fsync(temp_fd) == -1) {
        success = 0;
    }

    if (close(temp_fd) == -1) {
        success = 0;
    }

    if (!success) {
        unlink(tmpl);
        free(tmpl);
        return -1;
    }

    // Atomically replace the old log with the new rotated/copied log
    if (rename(tmpl, path) != 0) {
        unlink(tmpl);
        free(tmpl);
        return -1;
    }

    free(tmpl);
    return 0;
}

