short *resize_audio_frame(const short *in, int samples, int add_samples) {
    if (samples < 0 || add_samples < 0) {
        return nullptr;
    }

    // Prevent integer overflow when calculating new size
    if (add_samples > 0 && samples > __INT_MAX__ - add_samples) {
        return nullptr;
    }

    int new_samples = samples + add_samples;

    // Allocate buffer for the new audio frame
    short *out = (short *)malloc(new_samples * sizeof(short));
    if (!out) {
        return nullptr;
    }

    // Copy existing samples if input is provided and samples > 0
    if (in != nullptr && samples > 0) {
        std::memcpy(out, in, samples * sizeof(short));
    }

    // Zero out the newly added sample space to prevent heap buffer overflow/leakage of uninitialized data
    if (add_samples > 0) {
        std::memset(out + samples, 0, add_samples * sizeof(short));
    }

    return out;
}

