            pthread_rwlock_unlock(&c->rwlock);
            return 0;
        }
        curr = curr->next;
    }

    // Still not found, safely insert the new node at the head
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        pthread_rwlock_unlock(&c->rwlock);
        return -1; // Allocation failure
    }

    newNode->key = key;
    newNode->val = val;
    newNode->next = c->head;
    c->head = newNode;

    pthread_rwlock_unlock(&c->rwlock);
    return 0;
