    int has_digits = 0;

    while (i < len) {
        char c = chunk[i];
        // Ignore potential leading whitespace or handle standard hex digits
        if (c == '\r' || c == '\n') {
            // If we encounter newline before any digits, it might be a malformed chunk or empty line
            if (has_digits) break;
            i++;
            continue;
        }

        int digit = -1;
        if (c >= '0' && c <= '9') {
            digit = c - '0';
        } else if (c >= 'a' && c <= 'f') {
            digit = c - 'a' + 10;
        } else if (c >= 'A' && c <= 'F') {
            digit = c - 'A' + 10;
        } else {
            // Invalid hex char or extension separator (like ';')
            // For standard chunk decoding, we can stop parsing size at ';' or whitespace/CRLF
            if (c == ';' || c == ' ' || c == '\t') {
                // Consume until CRLF
                while (i < len && chunk[i] != '\n') {
                    i++;
                }
                if (i < len && chunk[i] == '\n') i++;
                break;
            }
            if (!has_digits) {
                return -1; // Invalid chunk size
            }
            break;
        }

        if (digit >= 0) {
            has_digits = 1;
            // Prevent overflow on 32-bit/64-bit
            if (chunk_size > (unsigned long)(((unsigned long)(-1)) >> 4)) {
                return -1; // Overflow
            }
            chunk_size = (chunk_size << 4) + (unsigned long)digit;
        }
        i++;
    }

    if (!has_digits) {
        return -1;
    }

    // If chunk size is 0, this is the last chunk
    if (chunk_size == 0) {
        return 0;
    }

    // Ensure output capacity is sufficient
    if ((unsigned long)out_cap < chunk_size) {
        return -1; // Output buffer too small
    }

    // Find the end of the size line if not already consumed
    // (In case we broke out early on ';' or similar)
    if (i < len && chunk[i - 1] != '\n') {
        while (i < len) {
            if (chunk[i] == '\n') {
                i++;
                break;
            }
            i++;
        }
    }

    // 2. Read chunk data
    unsigned long bytes_read = 0;
    while (bytes_read < chunk_size) {
        if (i >= len) {
            return -1; // Unexpected end of input
        }
        out[bytes_read++] = chunk[i++];
    }

    // 3. Consume trailing CRLF after the chunk data
    // Data might be followed by \r\n
    if (i < len && chunk[i] == '\r') {
        i++;
    }
    if (i < len && chunk[i] == '\n') {
        i++;
    }

    return (int)chunk_size;
