// Helper function to trim whitespace from both ends of a string
static std::string trim(const std::string& str) {
    size_t first = str.find_first_not_of(" \t\r\n");
    if (first == std::string::npos) {
        return "";
    }
    size_t last = str.find_last_not_of(" \t\r\n");
    return str.substr(first, (last - first + 1));
}

int parse_config_file_v1(const char *input, size_t len) {
    if (!input && len > 0) {
        return -1;
    }

    // If len is 0 and input is valid or null, consider it an empty config (success)
    if (len == 0) {
        return 0;
    }

    // Construct a string view/object from the input buffer and length
    std::string content(input, len);
    std::istringstream stream(content);
    std::string line;

    std::unordered_map<std::string, std::string> config;

    while (std::getline(stream, line)) {
        // Remove carriage returns if present (Windows line endings)
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }

        std::string trimmed_line = trim(line);

        // Skip empty lines and comments
        if (trimmed_line.empty() || trimmed_line[0] == '#' || trimmed_line[0] == ';') {
            continue;
        }

        // Find the delimiter '='
        size_t delimiter_pos = trimmed_line.find('=');
        if (delimiter_pos == std::string::npos) {
            // Invalid line format (missing '=')
            return -1;
        }

        std::string key = trim(trimmed_line.substr(0, delimiter_pos));
        std::string value = trim(trimmed_line.substr(delimiter_pos + 1));

        // Keys cannot be empty
        if (key.empty()) {
            return -1;
        }

        // Store or process the key-value pair
        config[key] = value;
    }

    return 0;
}

