#define EI_NIDENT 16

int parse_elf_ident(const unsigned char* stream, int stream_len) {
    if (stream == NULL || stream_len < EI_NIDENT) {
        return -1;
    }

    // Check ELF magic number: 0x7F 'E' 'L' 'F'
    if (stream[0] != 0x7F || 
        stream[1] != 'E' || 
        stream[2] != 'L' || 
        stream[3] != 'F') {
        return -1;
    }

    // Extract architecture class (EI_CLASS: index 4)
    // 1 = 32-bit, 2 = 64-bit
    unsigned char elf_class = stream[4];
    if (elf_class != 1 && elf_class != 2) {
        return -1;
    }

    // Extract data encoding (EI_DATA: index 5)
    // 1 = little endian, 2 = big endian
    unsigned char elf_data = stream[5];
    if (elf_data != 1 && elf_data != 2) {
        return -1;
    }

    // Extract ELF version (EI_VERSION: index 6)
    // Must be EV_CURRENT (1)
    if (stream[6] != 1) {
        return -1;
    }

    return 0;
}

