    // Skip leading whitespace
    while (*in != '\0' && isspace((unsigned char)*in)) {
        in++;
    }

    // If we reached the end of the string, return 0 length token
    if (*in == '\0') {
        *token_out = (char*)malloc(1);
        if (!*token_out) return -1;
        (*token_out)[0] = '\0';
        return 0;
    }

    const char* start = in;
    int len = 0;

    // Check if the token is quoted
    if (*in == '"' || *in == '\'') {
        char quote = *in;
        start++; // Skip opening quote
        in++;

        const char* q_start = in;
        while (*in != '\0' && *in != quote) {
            in++;
        }

        len = (int)(in - q_start);
        *token_out = (char*)malloc(len + 1);
        if (!*token_out) return -1;

        memcpy(*token_out, q_start, len);
        (*token_out)[len] = '\0';

        // Advance past closing quote if present
        if (*in == quote) {
            in++;
        }
    } else {
        // Unquoted token: read until whitespace or end of string
        while (*in != '\0' && !isspace((unsigned char)*in)) {
            in++;
        }

        len = (int)(in - start);
        *token_out = (char*)malloc(len + 1);
        if (!*token_out) return -1;

        memcpy(*token_out, start, len);
        (*token_out)[len] = '\0';
    }

    return len;
}

