    while (*in != '\0' && isspace((unsigned char)*in)) {
        in++;
    }

    // If we reached the end of the string, return 0 (no token)
    if (*in == '\0') {
        *token_out = NULL;
        return 0;
    }

    const char* start = in;

    // Check for quoted string
    if (*in == '"' || *in == '\'') {
        char quote = *in;
        start++; // Skip opening quote
        in++;

        while (*in != '\0' && *in != quote) {
            in++;
        }

        size_t len = (size_t)(in - start);
        char* token = (char*)malloc(len + 1);
        if (!token) {
            return -1; // Allocation failure
        }

        memcpy(token, start, len);
        token[len] = '\0';

        *token_out = token;

        // Return the number of characters consumed (including quotes if desired, 
        // or just the parsed span. Usually consume up to closing quote if present)
        if (*in == quote) {
            in++; // Skip closing quote
        }
        return (int)(in - (start - 1));
