    if (setuid(pwd->pw_uid) != 0) {
        return -1;
    }
    if (seteuid(pwd->pw_uid) != 0) {
        return -1;
    }

    // Verify that the privileges were successfully dropped
    if (setuid(0) == 0 || seteuid(0) == 0) {
