int verify_peer_cert_v1(const char *input, size_t len) {
    if (!input || len == 0) {
        return 0;
    }

    // Create a memory BIO containing the input certificate data
    BIO *bio = BIO_new_mem_buf((void *)input, (int)len);
    if (!bio) {
        return 0;
    }

    // Read the X509 certificate from the BIO
    X509 *cert = PEM_read_bio_X509(bio, NULL, NULL, NULL);
    BIO_free(bio);

    if (!cert) {
        return 0;
    }

    // Perform basic structural and validity verification of the certificate.
    // Since we don't have a full trust store or an SSL connection context passed in,
    // we verify the certificate's internal consistency, signature, and time validity
    // against itself (or basic self-signed checks if applicable).

    EVP_PKEY *pubkey = X509_get_pubkey(cert);
    if (!pubkey) {
        X509_free(cert);
        return 0;
    }

    // Verify the certificate's signature using its own public key 
    // (handles self-signed certificates, or establishes basic integrity)
    int ret = X509_verify(cert, pubkey);

    EVP_PKEY_free(pubkey);
    X509_free(cert);

    // X509_verify returns 1 on success, 0 on failure, < 0 on error.
    return (ret == 1) ? 1 : 0;
}

