    if (user_tok == NULL || valid_tok == NULL) {
        return 0;
    }

    size_t user_len = strlen(user_tok);
    size_t valid_len = strlen(valid_tok);

    // If lengths do not match, they are not equal. 
    // Note: Comparing lengths first is generally acceptable for standard tokens,
    // but to strictly avoid leaking length via timing, lengths should ideally be fixed.
    if (user_len != valid_len) {
        return 0;
    }

