char *duplicate_string(const char *s) {
    if (s == NULL) {
        return NULL;
    }

    size_t len = strlen(s);
    // Allocate space for the string plus the null terminator (fixing the potential off-by-one error)
    char *dup = (char *)malloc(len + 1);

    if (dup != NULL) {
        memcpy(dup, s, len + 1);
    }

    return dup;
}

